alter table public.business_products add column if not exists image_path text;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('business-product-images','business-product-images',false,5242880,array['image/jpeg','image/png','image/webp'])
on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
create policy "product_images_read" on storage.objects for select to authenticated using(bucket_id='business-product-images' and exists(select 1 from public.business_members m where m.business_id=(split_part(name,'/',1))::uuid and m.user_id=(select auth.uid())));
create policy "product_images_insert" on storage.objects for insert to authenticated with check(bucket_id='business-product-images' and exists(select 1 from public.business_members m where m.business_id=(split_part(name,'/',1))::uuid and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy "product_images_update" on storage.objects for update to authenticated using(bucket_id='business-product-images' and exists(select 1 from public.business_members m where m.business_id=(split_part(name,'/',1))::uuid and m.user_id=(select auth.uid()) and m.role in ('owner','admin'))) with check(bucket_id='business-product-images' and exists(select 1 from public.business_members m where m.business_id=(split_part(name,'/',1))::uuid and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));
create policy "product_images_delete" on storage.objects for delete to authenticated using(bucket_id='business-product-images' and exists(select 1 from public.business_members m where m.business_id=(split_part(name,'/',1))::uuid and m.user_id=(select auth.uid()) and m.role in ('owner','admin')));